std::atomic<int> shared_counter(0);

// Expected is passed by reference and updated on failure
int expected_val = 0;
int desired_val = 1;

// Lock-free loop attempting to increment shared_counter
while (!shared_counter.compare_exchange_weak(
    expected_val,
    desired_val,
    std::memory_order::acq_rel, // Success: Synchronization required
    std::memory_order::relaxed  // Failure: Only updating expected_val
)) {
    // If failure is spurious, loop continues with updated expected_val
    // If failure is real contention, expected_val is updated to current value
    desired_val = expected_val + 1;
}

// Note: Failure order cannot be stronger than Success order.
// Success order must be release or stronger if writing new value.
